function generatePipelineConfig() {
    return {
        name: 'CI/CD Pipeline',
        on: {
            push: { branches: ['main', 'develop'] },
            pull_request: { branches: ['main'] }
        },
        jobs: {
            lint: {
                'runs-on': 'ubuntu-latest',
                steps: [
                    { uses: 'actions/checkout@v4' },
                    { uses: 'actions/setup-node@v4', with: { 'node-version': '20', cache: 'npm' } },
                    { run: 'npm ci' },
                    { run: 'npm run lint' },
                    { run: 'npm run format:check' }
                ]
            },
            test: {
                'runs-on': 'ubuntu-latest',
                steps: [
                    { uses: 'actions/checkout@v4' },
                    { uses: 'actions/setup-node@v4', with: { 'node-version': '20', cache: 'npm' } },
                    { run: 'npm ci' },
                    { run: 'npm test -- --coverage' },
                    { uses: 'actions/upload-artifact@v4', with: { name: 'coverage', path: 'coverage/' } }
                ]
            },
            build: {
                'runs-on': 'ubuntu-latest',
                needs: ['lint', 'test'],
                steps: [
                    { uses: 'actions/checkout@v4' },
                    { uses: 'docker/setup-buildx-action@v3' },
                    { uses: 'docker/login-action@v3', with: { registry: 'ghcr.io', username: '${{ github.actor }}', password: '${{ secrets.GITHUB_TOKEN }}' } },
                    { uses: 'docker/build-push-action@v5', with: { push: true, tags: 'ghcr.io/${{ github.repository }}:${{ github.sha }}', 'cache-from': 'type=gha', 'cache-to': 'type=gha,mode=max' } }
                ]
            },
            'deploy-staging': {
                'runs-on': 'ubuntu-latest',
                needs: ['build'],
                environment: 'staging',
                steps: [
                    { uses: 'actions/checkout@v4' },
                    { run: 'echo "Deploying to staging..."' },
                    { run: 'echo "Deploy complete"' }
                ]
            },
            'deploy-production': {
                'runs-on': 'ubuntu-latest',
                needs: ['deploy-staging'],
                if: "github.ref == 'refs/heads/main'",
                environment: 'production',
                steps: [
                    { uses: 'actions/checkout@v4' },
                    { run: 'echo "Deploying to production..."' },
                    { run: 'echo "Deploy complete"' }
                ]
            }
        }
    };
}
